//! Golden tests against CPython 3.11 outputs (fixtures generated by `json.dumps`, `repr(float)`, `round`).
//! Regenerate with the generator script described in `tests/fixtures/README.md`.

use se_core::json::{self, DumpOptions, Value};
use se_core::pyfmt;

const FLOATS: &str = include_str!("fixtures/float_repr.txt");
const ROUNDS: &str = include_str!("fixtures/round.txt");
const CASES: &str = include_str!("fixtures/json_cases.json");

#[test]
fn test_float_repr_matches_cpython() {
    let mut n = 0;
    for line in FLOATS.lines() {
        let (bits, want) = line.split_once(' ').unwrap();
        let x = f64::from_bits(u64::from_str_radix(bits, 16).unwrap());
        assert_eq!(pyfmt::float_repr(x), want, "bits {bits}");
        n += 1;
    }
    assert!(n > 8000);
}

#[test]
fn test_round_matches_cpython() {
    for line in ROUNDS.lines() {
        let mut it = line.split(' ');
        let x = f64::from_bits(u64::from_str_radix(it.next().unwrap(), 16).unwrap());
        let n: u32 = it.next().unwrap().parse().unwrap();
        let want = f64::from_bits(u64::from_str_radix(it.next().unwrap(), 16).unwrap());
        let got = pyfmt::round_ndigits(x, n);
        assert_eq!(got.to_bits(), want.to_bits(), "round({x:?}, {n}) = {want:?}, got {got:?}");
    }
}

fn s(v: &Value) -> &str {
    v.as_str().unwrap()
}

#[test]
fn test_dumps_matches_cpython() {
    let fixture = json::parse(CASES).unwrap();
    for case in fixture.get("cases").unwrap().as_array().unwrap() {
        let doc = s(case.get("doc").unwrap());
        let v = json::parse(doc).unwrap_or_else(|e| panic!("{doc}: {e}"));
        assert_eq!(json::dumps(&v, false), s(case.get("compact").unwrap()), "compact {doc}");
        assert_eq!(json::dumps(&v, true), s(case.get("ascii").unwrap()), "ascii {doc}");
        let indent2 = DumpOptions { ensure_ascii: false, indent: Some(2), ..Default::default() };
        assert_eq!(json::dumps_with(&v, &indent2), s(case.get("indent2").unwrap()), "indent2 {doc}");
        let sorted = DumpOptions { ensure_ascii: true, indent: Some(1), sort_keys: true, ..Default::default() };
        assert_eq!(json::dumps_with(&v, &sorted), s(case.get("sorted_indent1").unwrap()), "sorted {doc}");
    }
}

#[test]
fn test_parse_errors_match_cpython() {
    let fixture = json::parse(CASES).unwrap();
    for case in fixture.get("errors").unwrap().as_array().unwrap() {
        let doc = s(case.get("doc").unwrap());
        let got = json::parse(doc).err().map(|e| e.to_string());
        let want = case.get("error").unwrap().as_str().map(str::to_string);
        assert_eq!(got, want, "doc {doc:?}");
    }
}
